div.script:

// State management
let money = parseFloat(localStorage.getItem('ep_money') || '15.00');
let day = parseInt(localStorage.getItem('ep_day') || '1', 10);
let timeRemaining = 60;
let dayActive = true;

let unlockedToppings = JSON.parse(localStorage.getItem('ep_toppings') || '{"sauce":true,"cheese":true,"pepperoni":false,"mushroom":false,"pepper":false}');
let hasAds = localStorage.getItem('ep_ads') === 'true';

let currentPizza = { sauce: false, cheese: false, pepperoni: false, mushroom: false, pepper: false };
let activeOrders = [];

// UI References
const moneyDisplay = document.getElementById('moneyDisplay');
const dayDisplay = document.getElementById('dayDisplay');
const timeDisplay = document.getElementById('timeDisplay');
const ordersList = document.getElementById('ordersList');

function saveGame() {
  localStorage.setItem('ep_money', money.toFixed(2));
  localStorage.setItem('ep_day', day.toString());
  localStorage.setItem('ep_toppings', JSON.stringify(unlockedToppings));
  localStorage.setItem('ep_ads', hasAds.toString());
}

function updateUI() {
  moneyDisplay.textContent = money.toFixed(2);
  dayDisplay.textContent = day;

  document.getElementById('btnPepperoni').disabled = !unlockedToppings.pepperoni;
  document.getElementById('btnMushroom').disabled = !unlockedToppings.mushroom;
  document.getElementById('btnPepper').disabled = !unlockedToppings.pepper;

  if (unlockedToppings.pepperoni) document.getElementById('buyPepBtn').disabled = true;
  if (unlockedToppings.mushroom) document.getElementById('buyMushBtn').disabled = true;
  if (unlockedToppings.pepper) document.getElementById('buyPep2Btn').disabled = true;
  if (hasAds) document.getElementById('buyAdBtn').disabled = true;
}

function generateOrder() {
  if (activeOrders.length >= 3) return;

  const possibleToppings = ['sauce', 'cheese'];
  if (unlockedToppings.pepperoni) possibleToppings.push('pepperoni');
  if (unlockedToppings.mushroom) possibleToppings.push('mushroom');
  if (unlockedToppings.pepper) possibleToppings.push('pepper');

  // Pick 2-4 toppings randomly
  let orderReq = { sauce: true, cheese: true };
  if (possibleToppings.length > 2 && Math.random() > 0.4) orderReq.pepperoni = true;
  if (unlockedToppings.mushroom && Math.random() > 0.5) orderReq.mushroom = true;
  if (unlockedToppings.pepper && Math.random() > 0.5) orderReq.pepper = true;

  // Calculate payout
  let basePayout = 8.00;
  if (orderReq.pepperoni) basePayout += 3.50;
  if (orderReq.mushroom) basePayout += 4.50;
  if (orderReq.pepper) basePayout += 5.00;
  if (hasAds) basePayout *= 1.15;

  const newOrder = {
    id: Date.now(),
    toppings: orderReq,
    payout: basePayout
  };

  activeOrders.push(newOrder);
  renderOrders();
}

function renderOrders() {
  ordersList.innerHTML = '';
  activeOrders.forEach((ord, idx) => {
    const ticket = document.createElement('div');
    ticket.className = 'ticket';

    let tagsHtml = '';
    if (ord.toppings.sauce) tagsHtml += '<span class="topping-tag">🥫 Sauce</span>';
    if (ord.toppings.cheese) tagsHtml += '<span class="topping-tag">🧀 Cheese</span>';
    if (ord.toppings.pepperoni) tagsHtml += '<span class="topping-tag">🥓 Pepperoni</span>';
    if (ord.toppings.mushroom) tagsHtml += '<span class="topping-tag">🍄 Mushroom</span>';
    if (ord.toppings.pepper) tagsHtml += '<span class="topping-tag">🫑 Pepper</span>';

    ticket.innerHTML = `
      <div style="display:flex; justify-shadow:space-between; font-weight:800; font-size:0.85rem; color:#38bdf8;">
        <span>ORDER #${idx + 1}</span>
        <span style="color:#22c55e;">+$${ord.payout.toFixed(2)}</span>
      </div>
      <div style="margin-top:4px;">${tagsHtml}</div>
    `;
    ordersList.appendChild(ticket);
  });
}

function addIngredient(type) {
  currentPizza[type] = true;
  renderPizza();
}

function clearPizza() {
  currentPizza = { sauce: false, cheese: false, pepperoni: false, mushroom: false, pepper: false };
  renderPizza();
}

function renderPizza() {
  document.getElementById('pizzaSauce').className = `pizza-sauce ${currentPizza.sauce ? 'active' : ''}`;
  document.getElementById('pizzaCheese').className = `pizza-cheese ${currentPizza.cheese ? 'active' : ''}`;

  const overlay = document.getElementById('toppingOverlay');
  overlay.innerHTML = '';

  if (currentPizza.pepperoni) {
    for (let i = 0; i < 6; i++) {
      const pep = document.createElement('div');
      pep.style.cssText = `position:absolute; width:28px; height:28px; background:#b91c1c; border-radius:50%; border:2px solid #991b1b; top:${20 + (i*25)%120}px; left:${30 + (i*35)%130}px;`;
      overlay.appendChild(pep);
    }
  }

  if (currentPizza.mushroom) {
    for (let i = 0; i < 5; i++) {
      const mush = document.createElement('div');
      mush.style.cssText = `position:absolute; width:22px; height:22px; background:#e2e8f0; border-radius:40%; top:${40 + (i*30)%110}px; left:${25 + (i*40)%120}px;`;
      overlay.appendChild(mush);
    }
  }

  if (currentPizza.pepper) {
    for (let i = 0; i < 5; i++) {
      const pep = document.createElement('div');
      pep.style.cssText = `position:absolute; width:10px; height:26px; background:#16a34a; border-radius:6px; transform:rotate(${i*35}deg); top:${35 + (i*28)%110}px; left:${45 + (i*30)%110}px;`;
      overlay.appendChild(pep);
    }
  }
}

function bakeAndServe() {
  if (activeOrders.length === 0) return;

  // Find matching order
  let matchIdx = -1;
  for (let i = 0; i < activeOrders.length; i++) {
    const req = activeOrders[i].toppings;
    const matches = 
      Boolean(req.sauce) === Boolean(currentPizza.sauce) &&
      Boolean(req.cheese) === Boolean(currentPizza.cheese) &&
      Boolean(req.pepperoni) === Boolean(currentPizza.pepperoni) &&
      Boolean(req.mushroom) === Boolean(currentPizza.mushroom) &&
      Boolean(req.pepper) === Boolean(currentPizza.pepper);

    if (matches) {
      matchIdx = i;
      break;
    }
  }

  if (matchIdx !== -1) {
    money += activeOrders[matchIdx].payout;
    activeOrders.splice(matchIdx, 1);
    clearPizza();
    renderOrders();
    saveGame();
    updateUI();
    generateOrder();
  } else {
    alert('Recipe mismatch! Check order ticket ingredients.');
  }
}

function buyUpgrade(type, cost) {
  if (money < cost) {
    alert('Not enough funds in bank!');
    return;
  }

  money -= cost;
  if (type === 'pep') unlockedToppings.pepperoni = true;
  if (type === 'mush') unlockedToppings.mushroom = true;
  if (type === 'pepper') unlockedToppings.pepper = true;
  if (type === 'ad') hasAds = true;

  saveGame();
  updateUI();
}

// Main Day Loop Timer
setInterval(() => {
  if (!dayActive) return;

  timeRemaining--;
  timeDisplay.textContent = timeRemaining + 's';

  if (timeRemaining % 7 === 0) {
    generateOrder();
  }

  if (timeRemaining <= 0) {
    dayActive = false;
    alert(`Day ${day} Completed! Starting Day ${day + 1}...`);
    day++;
    timeRemaining = 60;
    activeOrders = [];
    clearPizza();
    saveGame();
    updateUI();
    dayActive = true;
    generateOrder();
  }
}, 1000);

// Init Game
updateUI();
generateOrder();
generateOrder();
